    "    t := x * 4.0 + y * 8.0 + z + f64(s.f ?\? 0.0) * 2.0 + f64(s.g ?\? 0.0) * 10.0\n"
    "    r := int(t + (d[0] ?\? 3.0) * 4.0)\n"
    "    return r + so_fsum(x * 2.0, y * 4.0, SoFl.{ .f = 1.5, .g = 2.5 })\n"
    "}\n"
    "\n"
    "fn so_bytes(xs: []?u8, n: int) -> int {\n"
    "    for i in 0..xs.len {\n"
    "        if (i + n) % 2 == 0 {\n"
    "            xs[i] = u8(i + 1)\n"
    "        }\n"
    "    }\n"
    "    t := 0\n"
    "    for x in xs {\n"
    "        t = t * 10 + int(x ?\? 0)\n"
    "    }\n"
    "    return t\n"
    "}\n"
    "\n"
    "fn so_slices(a: int, b: int) -> int {\n"
    "    bs: [5]?u8\n"
    "    bs[4] = 9\n"
    "    return so_bytes(bs[0..5], a & 1) * 10 + int(bs[(b & 3)] ?\? 7)\n"
    "}\n"
    "\n"
    "fn so_nested(a: int, b: int) -> int {\n"
    "    o: SoOut\n"
    "    if a > 0 {\n"
    "        o.i.v = i32(a)\n"
    "    }\n"
    "    o.i.w[b & 1] = a > b\n"
    "    o.k = o.i.v ?\? 4\n"
    "    p := o\n"
    "    q := &p.i\n"
    "    q.w[0] = nil\n"
    "    return int(p.i.v ?\? -5) * 1000 + (if o.i.w[0] ?\? false then 100 else 200) +\n"
    "           (if p.i.w[1] ?\? true then 10 else 20) + (p.k ?\? 0)\n"
    "}\n"
    "\n"
    "fn so_pack(xs: ..?int) -> int {\n"
    "    t := 0\n"
    "    for x in xs {\n"
    "        t = t * 10 + (x ?\? 7)\n"
    "    }\n"
    "    return t * 10 + xs.len\n"
    "}\n"
    "\n"
    "fn so_halves(xs: ..?f32) -> int {\n"
    "    t: f32 = 0.0\n"
    "    for i in 0..xs.len {\n"
    "        t = t * 2.0 + (xs[i] ?\? 0.5)\n"
    "    }\n"
    "    return int(t * 4.0)\n"
    "}\n"
    "\n"
    "fn so_rest(a: int, b: int) -> int {\n"
    "    n: ?int = nil\n"
    "    if a > 3 {\n"
    "        n = b & 7\n"
    "    }\n"
    "    f: ?f32 = nil\n"
    "    if b > 1 {\n"
    "        f = 1.5\n"
    "    }\n"
    "    return so_pack(1, nil, a & 7, n) * 1000 + so_pack() * 100 + so_pack(n) + so_halves(f, nil, 2.0) * 1000000\n"
    "}\n"
    "\n"
    "fn so_pick(a: int) -> (int, ?bool) {\n"
    "    if a > 0 {\n"
    "        return a, a > 5\n"
    "    }\n"
    "    return a, nil\n"
    "}\n"
    "\n"
    "fn so_named(a: int) -> (q: ?int, r: int) {\n"
    "    if a > 2 {\n"
    "        q = a * 2\n"
    "    }\n"
    "    r = a\n"
    "    return\n"
    "}\n"
    "\n"
    "fn so_tuples(a: int, b: int) -> int {\n"
    "    x, y := so_pick(a)\n"
    "    q, r := so_named(b)\n"
    "    return x * 1000 + (if y ?\? true then 100 else 200) + (q ?\? -1) * 10 + r\n"
    "}\n";

