const char ERROR_UNIONS[] =
    "enum ErColor: u8 { red, green, blue }\n"
    "\n"
    "struct ErBox { e: error, n: int }\n"
    "\n"
    "er_last: error = error.start\n"
    "const er_limit: error = error.limit\n"
    "\n"
    "fn er_div(a: int, b: int) -> !int {\n"
    "    if b == 0 {\n"
    "        return error.divide_by_zero\n"
    "    }\n"
    "    if a < 0 {\n"
    "        return error.negative\n"
    "    }\n"
    "    return a / b\n"
    "}\n"
    "\n"
    "fn er_code(e: error) -> int {\n"
    "    if e == error.divide_by_zero {\n"
    "        return 1\n"
    "    }\n"
    "    if e == error.negative {\n"
    "        return 2\n"
    "    }\n"
    "    return 3\n"
    "}\n"
    "\n"
    "fn er_basic(a: int, b: int) -> int {\n"
    "    x := er_div(a, b) catch -1\n"
    "    y := er_div(b, a) catch e => er_code(e) * -10\n"
    "    z := er_div(a + b, b & 3) catch e => if e == error.negative then -100 else -200\n"
    "    return (x * 1000 + y) * 1000 + z\n"
    "}\n"
    "\n"
    "fn er_check(x: int) -> !void {\n"
    "    if x > 100 {\n"
    "        return error.too_big\n"
    "    }\n"
    "    if x < -100 {\n"
    "        return error.too_small\n"
    "    }\n"
    "}\n"
    "\n"
    "fn er_sum(a: int, b: int) -> !int {\n"
    "    return try er_div(a, 2) + try er_div(b, 3)\n"
    "}\n"
    "\n"
    "fn er_chain(a: int, b: int) -> !int {\n"
    "    x := try er_sum(a, b)\n"
    "    try er_check(x)\n"
    "    return x * 2\n"
    "}\n"
    "\n"
    "fn er_propagate(a: int, b: int) -> int {\n"
    "    return er_chain(a, b) catch e => -er_code(e)\n"
    "}\n"
    "\n"
    "fn er_both(a: int, b: int) -> !void {\n"
    "    try er_check(a)\n"
    "    try er_check(b)\n"
    "    _ = try er_div(a, b)\n"
    "    if a == b {\n"
    "        return error.same\n"
    "    }\n"
    "}\n"
    "\n"
    "fn er_void(a: int, b: int) -> int {\n"
    "    t := 0\n"
    "    er_both(a, b) catch e => {\n"
    "        t = if e == error.too_big then 1 else if e == error.too_small then 2 else if e == error.same then 3 else 4\n"
    "    }\n"
    "    er_check(a * 2) catch {\n"
    "        t += 10\n"
    "    }\n"
    "    er_check(b - a) catch e => {\n"
    "        if e == error.too_small {\n"
    "            return t + 100\n"
    "        }\n"
    "        t += 1000\n"
    "    }\n"
    "    return t\n"
    "}\n"
    "\n"
    "fn er_half(x: int) -> !f64 {\n"
    "    if x < 0 {\n"
    "        return error.negative\n"
    "    }\n"
    "    return f64(x) * 0.5\n"
    "}\n"
    "\n"
    "fn er_quarter(x: int) -> !f32 {\n"
    "    if x > 50 {\n"
    "        return error.too_big\n"
    "    }\n"
    "    return f32(x) * 0.25\n"
    "}\n"
    "\n"
    "fn er_mix(a: int, b: int) -> !f64 {\n"
    "    return try er_half(a) + f64(try er_quarter(b))\n"
    "}\n"
    "\n"
    "fn er_floats(a: int, b: int) -> int {\n"
    "    x := er_half(a) catch -1.0\n"
    "    y := er_quarter(b) catch e => if e == error.too_big then 100.0 else 200.0\n"
    "    z := er_mix(a, b) catch -2.0\n"
    "    return (int(x * 10.0) * 100000 + int(y * 100.0)) * 100000 + int(z * 100.0)\n"
    "}\n"
    "\n"
    "fn er_byte(x: int) -> !u8 {\n"
    "    if x < 0 or x > 255 {\n"
    "        return error.out_of_range\n"
    "    }\n"
    "    return u8(x)\n"
    "}\n"
    "\n"
    "fn er_neg(x: int) -> !i32 {\n"
    "    if x == 0 {\n"
    "        return error.zero\n"
    "    }\n"
    "    return i32(-(x & 1023))\n"
    "}\n"
    "\n"
    "fn er_flag(x: int) -> !bool {\n"
    "    if x == 0 {\n"
    "        return error.zero\n"
    "    }\n"
    "    return x > 0\n"
    "}\n"
    "\n"
    "fn er_color(x: int) -> !ErColor {\n"
    "    if x < 0 {\n"
    "        return error.negative\n"
    "    }\n"
    "    if x == 0 {\n"
    "        return ErColor.red\n"
    "    }\n"
    "    return if x > 5 then ErColor.blue else ErColor.green\n"
    "}\n"
    "\n"
    "fn er_small(a: int, b: int) -> int {\n"
    "    p := er_byte(a) catch 7\n"
    "    q := er_neg(b) catch 3\n"
    "    f := er_flag(a - b) catch false\n"
    "    c := er_color(b) catch .green\n"
    "    t := int(p) * 100000 + int(q) * 10\n"
    "    return (t + (if f then 1 else 0)) * 10 + int(c)\n"
    "}\n"
    "\n"
    "fn er_at(p: *[4]int, i: int) -> !*int {\n"
    "    if i < 0 or i >= 4 {\n"
    "        return error.out_of_range\n"
    "    }\n"
    "    return &p.*[i]\n"
    "}\n"
    "\n"
    "fn er_find(p: *[4]int, v: int) -> !?*int {\n"
    "    if v < 0 {\n"
    "        return error.negative\n"
    "    }\n"
    "    for i in 0..4 {\n"
    "        if p.*[i] == v {\n"
    "            return &p.*[i]\n"
    "        }\n"
    "    }\n"
    "    return nil\n"
    "}\n"
    "\n"
    "fn er_pointers(a: int, b: int) -> int {\n"
    "    xs: [4]int = .[3, 1, 4, 1]\n"
    "    q := er_at(&xs, a) catch &xs[0]\n"
    "    q.* += 10\n"
    "    r := er_find(&xs, b) catch nil\n"
    "    if r != nil {\n"
    "        r!!.* += 50\n"
    "    }\n"
    "    n := 0\n"
    "    if (er_find(&xs, a) catch nil) == nil {\n"
    "        n = 1\n"
    "    }\n"
    "    return ((xs[0] * 100 + xs[1]) * 100 + xs[2]) * 100 * 100 + xs[3] * 10 + n\n"
    "}\n"
    "\n"
    "fn er_pick(a: int, b: int) -> !int {\n"
    "    return if a > b then er_div(a, b) else er_div(b, a)\n"
    "}\n"
    "\n"
    "fn er_ifs(a: int, b: int) -> int {\n"
    "    x := (if a > 0 then er_div(a, 2) else er_div(b, 0)) catch -5\n"
    "    y := er_pick(a, b) catch e => er_code(e) * -1\n"
    "    z := (if a == b then error.same else er_div(a, 1)) catch e => if e == error.same then -7 else -8\n"
    "    return (x * 1000 + y) * 1000 + z\n"
    "}\n"
    "\n"
    "fn er_steps(p: *int, a: int, b: int) -> !int {\n"
    "    defer p.* = p.* * 10 + 1\n"
    "    x := try er_div(a, b)\n"
    "    defer p.* = p.* * 10 + 2\n"
    "    try er_check(x)\n"
    "    return x\n"
    "}\n"
    "\n"
    "fn er_defer(a: int, b: int) -> int {\n"
    "    t := 0\n"
    "    r := er_steps(&t, a, b) catch e => er_code(e) * -1\n"
    "    return r * 1000 + t\n"
    "}\n"
    "\n"
    "fn er_loop(a: int, b: int) -> int {\n"
    "    t := 0\n"
    "    for i in 0..6 {\n"
    "        defer t = t * 2 + 1\n"
    "        v := er_div(a - i, b & 3) catch e => {\n"
    "            if e == error.negative {\n"
    "                break\n"
    "            }\n"
    "            continue\n"
    "        }\n"
    "        t += v\n"
    "    }\n"
    "    return t\n"
    "}\n"
    "\n"
    "fn er_retry(a: int, b: int) -> !int {\n"
    "    return er_div(a, b) catch e => if e == error.divide_by_zero then try er_div(b, 1) else -1\n"
    "}\n"
    "\n"
    "fn er_nested(a: int, b: int) -> int {\n"
    "    x := er_div(a, b) catch (er_div(b, a) catch (er_div(a + b, 1) catch -9))\n"
    "    y := er_retry(a, b) catch e => er_code(e) * -100\n"
    "    return x * 10000 + y\n"
    "}\n"
    "\n"
    "fn er_name(e: error) -> int {\n"
    "    if e == error.negative {\n"
    "        return 1\n"
    "    }\n"
    "    if e == error.divide_by_zero {\n"
    "        return 2\n"
    "    }\n"
    "    if e == er_limit {\n"
    "        return 3\n"
    "    }\n"
    "    if e == error.start {\n"
    "        return 4\n"
    "    }\n"
    "    return 5\n"
    "}\n"
    "\n"
    "fn er_values(a: int, b: int) -> int {\n"
    "    e: error = if a > b then error.negative else er_limit\n"
    "    box := ErBox.{ error.divide_by_zero, a }\n"
    "    if b > 3 {\n"
    "        box.e = e\n"
    "    }\n"
    "    errs: [3]error = .[error.start, er_limit, e]\n"
    "    k := (a & 1) + (b & 1)\n"
    "    return er_name(e) * 1000 + er_name(box.e) * 100 + er_name(errs[k]) * 10 + er_name(er_last)\n"
    "}\n"
    "\n"
    "fn er_fail(e: error, x: int) -> !void {\n"
    "    if x > 0 {\n"
    "        return e\n"
    "    }\n"
    "}\n"
    "\n"
    "fn er_give(e: error, x: int) -> !int {\n"
    "    if x > 0 {\n"
    "        return e\n"
    "    }\n"
    "    return x\n"
    "}\n"
    "\n"
    "fn er_add3(x: int, y: int, z: int) -> int {\n"
    "    return x * 100 + y * 10 + z\n"
    "}\n"
    "\n"
    "fn er_args(a: int, b: int) -> !int {\n"
    "    try er_fail(error.negative, a - 100)\n"
    "    return er_add3(try er_div(a, 1), try er_div(b, 1), try er_give(error.same, b - a))\n"
    "}\n"
    "\n"
    "fn er_argcalls(a: int, b: int) -> int {\n"
    "    return er_args(a, b) catch e => er_name(e) * -1\n"
    "}\n"
    "\n"
    "fn er_bump(p: *int) -> int {\n"
    "    p.* += 100\n"
    "    return 1\n"
    "}\n"
    "\n"
    "fn er_order(a: int, b: int) -> int {\n"
    "    t := a\n"
    "    x := t + (er_div(a, b) catch er_bump(&t))\n"
    "    return x * 1000 + t\n"
    "}\n"
    "\n"
    "const er_many := error.[\n"
    "    error.m0, error.m1, error.m2, error.m3, error.m4, error.m5, error.m6, error.m7, error.m8, error.m9,\n"
    "    error.m10, error.m11, error.m12, error.m13, error.m14, error.m15, error.m16, error.m17, error.m18, error.m19,\n"
    "    error.m20, error.m21, error.m22, error.m23, error.m24, error.m25, error.m26, error.m27, error.m28, error.m29,\n"
    "    error.m30, error.m31, error.m32, error.m33, error.m34, error.m35, error.m36, error.m37, error.m38, error.m39,\n"
    "    error.m40, error.m41, error.m42, error.m43, error.m44, error.m45, error.m46, error.m47, error.m48, error.m49,\n"
    "    error.m50, error.m51, error.m52, error.m53, error.m54, error.m55, error.m56, error.m57, error.m58, error.m59,\n"
    "    error.m60, error.m61, error.m62, error.m63, error.m64, error.m65, error.m66, error.m67, error.m68, error.m69,\n"
    "    error.m70, error.m71, error.m72, error.m73, error.m74, error.m75, error.m76, error.m77, error.m78, error.m79,\n"
    "    error.m80, error.m81, error.m82, error.m83, error.m84, error.m85, error.m86, error.m87, error.m88, error.m89,\n"
    "    error.m90, error.m91, error.m92, error.m93, error.m94, error.m95, error.m96, error.m97, error.m98, error.m99,\n"
    "    error.m100, error.m101, error.m102, error.m103, error.m104, error.m105, error.m106, error.m107, error.m108, error.m109,\n"
    "    error.m110, error.m111, error.m112, error.m113, error.m114, error.m115, error.m116, error.m117, error.m118, error.m119,\n"
    "    error.m120, error.m121, error.m122, error.m123, error.m124, error.m125, error.m126, error.m127, error.m128, error.m129,\n"
    "    error.m130, error.m131, error.m132, error.m133, error.m134, error.m135, error.m136, error.m137, error.m138, error.m139,\n"
    "    error.m140, error.m141, error.m142, error.m143, error.m144, error.m145, error.m146, error.m147, error.m148, error.m149,\n"
    "    error.m150, error.m151, error.m152, error.m153, error.m154, error.m155, error.m156, error.m157, error.m158, error.m159,\n"
    "    error.m160, error.m161, error.m162, error.m163, error.m164, error.m165, error.m166, error.m167, error.m168, error.m169,\n"
    "    error.m170, error.m171, error.m172, error.m173, error.m174, error.m175, error.m176, error.m177, error.m178, error.m179,\n"
    "    error.m180, error.m181, error.m182, error.m183, error.m184, error.m185, error.m186, error.m187, error.m188, error.m189,\n"
    "    error.m190, error.m191, error.m192, error.m193, error.m194, error.m195, error.m196, error.m197, error.m198, error.m199,\n"
    "    error.m200, error.m201, error.m202, error.m203, error.m204, error.m205, error.m206, error.m207, error.m208, error.m209,\n"
    "    error.m210, error.m211, error.m212, error.m213, error.m214, error.m215, error.m216, error.m217, error.m218, error.m219,\n"
    "    error.m220, error.m221, error.m222, error.m223, error.m224, error.m225, error.m226, error.m227, error.m228, error.m229,\n"
    "    error.m230, error.m231, error.m232, error.m233, error.m234, error.m235, error.m236, error.m237, error.m238, error.m239,\n"
    "    error.m240, error.m241, error.m242, error.m243, error.m244, error.m245, error.m246, error.m247, error.m248, error.m249,\n"
    "    error.m250, error.m251, error.m252, error.m253, error.m254, error.m255, error.m256, error.m257, error.m258, error.m259,\n"
    "    error.m260, error.m261, error.m262, error.m263, error.m264, error.m265, error.m266, error.m267, error.m268, error.m269,\n"
    "    error.m270, error.m271, error.m272, error.m273, error.m274, error.m275, error.m276, error.m277, error.m278, error.m279,\n"
    "    error.m280, error.m281, error.m282, error.m283, error.m284, error.m285, error.m286, error.m287, error.m288, error.m289,\n"
    "    error.m290, error.m291, error.m292, error.m293, error.m294, error.m295, error.m296, error.m297, error.m298, error.m299,\n"
    "]\n"
    "\n"
    "fn er_nth(i: int) -> !void {\n"
    "    if i >= 0 and i < 300 {\n"
    "        return er_many[i]\n"
    "    }\n"
    "}\n"
    "\n"
    "fn er_scan(a: int, b: int) -> int {\n"
    "    n := 0\n"
    "    for i in 0..300 {\n"
    "        er_nth(i) catch {\n"
    "            n += 1\n"
    "        }\n"
    "    }\n"
    "    hit := 0\n"
    "    er_nth(a) catch e => {\n"
    "        hit = if e == er_many[a] then 1 else 2\n"
    "    }\n"
    "    return n * 10 + hit + b\n"
    "}\n"
    "\n"
    "fn er_far(a: int, b: int) -> !int {\n"
    "    if a > b {\n"
    "        return error.m299\n"
    "    }\n"
    "    return a - b\n"
    "}\n"
    "\n"
    "fn er_touch(p: *int) {\n"
    "    p.* += 1\n"
    "}\n"
    "\n"
    "fn er_late(a: int, b: int) -> !int {\n"
    "    t := 0\n"
    "    defer er_touch(&t)\n"
    "    return er_far(a, b)\n"
    "}\n"
    "\n"
    "fn er_wide(a: int, b: int) -> int {\n"
    "    x := er_far(a, b) catch e => if e == error.m299 then 300 else -1\n"
    "    y := er_late(b, a) catch e => if e == error.m299 then 600 else -2\n"
    "    return x * 1000 + y\n"
    "}\n";

